    {"customer_id": 1, "total": 30},
    {"customer_id": 2, "total": 45},
    {"customer_id": 1, "total": 25},
    {"customer_id": 3, "total": 20},
    {"customer_id": 2, "total": 10},
]

# GROUP BY customer_id: one entry per customer
groups = {}
for row in orders:
    key = row["customer_id"]
    if key not in groups:
        groups[key] = {"count": 0, "sum": 0}
    groups[key]["count"] += 1
    groups[key]["sum"] += row["total"]

for key, g in groups.items():
    print(key, g["count"], g["sum"])

