CREATE TABLE orders (
  id          INTEGER PRIMARY KEY,
  customer_id INTEGER NOT NULL
              REFERENCES customers(id),
  total       NUMERIC(10, 2) NOT NULL
              CHECK (total >= 0),
  status      TEXT DEFAULT 'pending'
);

